// Image assembly copies independently compiled artifacts only. The daemon must
// never execute candidate source in a privileged Dockerfile RUN instruction.
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// Identity bytes and Dockerfile are generated by the trusted control program,
// not supplied by candidate source. No config or vault directory is copied.
type sourceBuildImagePlan struct {
	Dockerfile []byte
	Identity   []byte
	SourceLock []byte
}

// The caller verifies the digest-named local base alias resolves to the exact
// incumbent image immediately before building with pull disabled. Inherited
// module/toolchain caches remain unchanged; every source tree is copied cleanly.
func planSourceBuildImage(request reviewedSourceBuildRequest, binary []byte) (*sourceBuildImagePlan, error) {
	if err := validateSourceBuildRequest(request); err != nil {
		return nil, err
	}
	commit := request.Proposal.Commits["server"]
	binaryDigest, err := verifySourceBuildBinary(binary, commit)
	if err != nil {
		return nil, err
	}
	return sourceBuildImagePlanForDigest(request, binaryDigest)
}

// Internal formatter accepts only already validated identities. Keeping it
// separate permits deterministic format/containment tests without real images.
func sourceBuildImagePlanForDigest(request reviewedSourceBuildRequest, binaryDigest string) (*sourceBuildImagePlan, error) {
	if err := validateSourceBuildRequest(request); err != nil {
		return nil, err
	}
	if !validSha256(binaryDigest) {
		return nil, errors.New("source image requires an authenticated binary digest")
	}
	commit := request.Proposal.Commits["server"]
	lock, err := json.MarshalIndent(evaluatorSourceLock{Schema: 1, Repositories: request.Proposal.Commits}, "", "  ")
	if err != nil {
		return nil, err
	}
	lock = append(lock, '\n')
	lockHash, manifestHash, emptyPatchHash := sha256.Sum256(lock), sha256.Sum256(request.SourceManifest), sha256.Sum256(nil)
	identity, err := json.MarshalIndent(map[string]any{
		"schema": 1, "image_kind": "evaluator-base", "base_sha": commit, "build_sha": commit,
		"source_epoch": request.SourceGeneration, "source_config_sha256": hex.EncodeToString(manifestHash[:]),
		"patch_sha256": hex.EncodeToString(emptyPatchHash[:]), "policy_sha256": nil,
		"source_lock_sha256": hex.EncodeToString(lockHash[:]), "simulator_sha256": binaryDigest, "paths": []string{},
	}, "", "  ")
	if err != nil {
		return nil, err
	}
	// All interpolated values have already been validated as hashes, integers
	// or booleans. No candidate path, command, title or shell syntax enters it.
	dockerfile := fmt.Sprintf(`FROM urnetwork/sim-latency-evaluator-base-id:%s
COPY source/ /workspace/
COPY --chmod=0555 sim-latency /opt/urnetwork/bin/sim-latency
COPY --chmod=0444 sim-latency.yml /opt/urnetwork/sim-latency.yml
COPY --chmod=0444 source-lock.json /opt/urnetwork/source-lock.json
COPY --chmod=0444 image-identity.json /opt/urnetwork/image-identity.json
COPY --chmod=0444 canonical.patch /opt/urnetwork/submission/canonical.patch
LABEL org.opencontainers.image.title="URnetwork sim-latency evaluator base" \
      org.opencontainers.image.revision="%s" \
      com.urnetwork.competition.image-kind="evaluator-base" \
      com.urnetwork.competition.base-sha="%s" \
      com.urnetwork.competition.source-epoch="%d" \
      com.urnetwork.competition.source-config-sha256="%s" \
      com.urnetwork.competition.source-lock-sha256="%s" \
      com.urnetwork.competition.development-snapshot="false" \
      com.urnetwork.competition.staging="%t"
USER 65532:65532
WORKDIR /workspace/server
`, strings.TrimPrefix(request.Proposal.EvaluatedImageDigest, "sha256:"), commit, commit, request.SourceGeneration,
		hex.EncodeToString(manifestHash[:]), hex.EncodeToString(lockHash[:]), request.Proposal.Staging)
	return &sourceBuildImagePlan{Dockerfile: []byte(dockerfile), Identity: append(identity, '\n'), SourceLock: lock}, nil
}
